        )

    def test_new_pairs_preserve_order_duplicates_and_blanks(self):
        self.assertEqual(
            solution.append_query("/p", [("x", "1"), ("x", "2"), ("blank", ""), ("x", "3")]),
            "/p?x=1&x=2&blank=&x=3",
        )

