        self.assertEqual(
            solution.append_query("/p", [("sp", "a b"), ("plus", "a+b"), ("amp", "a&b")]),
            "/p?sp=a+b&plus=a%2Bb&amp=a%26b",
        )

    def test_unicode_encoding(self):
        self.assertEqual(
            solution.append_query("/p", [("word", "caf\u00e9")]),
            "/p?word=caf%C3%A9",
        )

