        self.assertEqual(solution.append_query("/p?a=1", []), "/p?a=1")

    def test_empty_query_and_no_pairs(self):
        self.assertEqual(solution.append_query("/p", []), "/p")

    def test_dict_pairs_supported(self):
        self.assertEqual(
            solution.append_query("/p?a=1", {"b": "2"}),
            "/p?a=1&b=2",
        )


